def maximum_Sum(lists):
    max_sum = float('-inf')
    for lst in lists:
        current_sum = sum(lst)
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum
```

```python
def find_Product(arr, n):
    count_dict = {}
    for i in range(n):
        if arr[i] in count_dict:
            count_dict[arr[i]] += 1
        else:
            count_dict[arr[i]] = 1

    product = 1
    for key, value in count_dict.items():
        if value == 1:
            product *= key

    return product
```
